        '<b>빅맥 지수(같은 햄버거 값으로 통화 가치를 비교하는 지표)도 못 믿는다.</b> 골드만삭스는 이를 근거로 엔/달러 적정치를 90엔으로 보는데 실제는 한때 160엔이었다. 50% 이상 저평가라는 계산이다. 류 전 국장은 인건비와 관세가 다른데 빅맥 하나로 비교하는 게 타당하냐며, 차라리 갤럭시와 아이폰을 비교하자고 받아친다.',
        '<b>결정적 반박은 진행자에게서 나온다.</b> 기사가 든 요인은 실질금리, 저평가, 재정 신뢰, 캐리트레이드(금리 낮은 통화로 빌려 금리 높은 곳에 투자하는 것), 해외투자 소득, 다카이치 정부의 재정 확대다. 그런데 전부 원래부터 있던 것이다. 그걸로는 왜 요즘 더 심해졌는지를 설명하지 못한다.',
        '<b>오늘의 진짜 관찰.</b> 그 기사에는 수급 요인이 단 하나도 없다. 반면 한국에서 원화 약세를 말할 땐 거의 항상 서학개미가 나간다, 외국인이 리밸런싱(비중을 다시 맞추려 사고파는 것)한다, 삼성이 수출대금을 안 바꾼다부터 나온다.',
        '<b>사는 물량과 파는 물량은 언제나 같다.</b> 누가 팔았다면 누군가는 반드시 샀다. 많이 팔아서 내렸다는 말 자체가 인과 오해다. 값을 움직이는 건 물량이 아니라 급하게 사느냐 급하게 파느냐다.',
        '<b>외환 개입은 사이드카(급변할 때 잠깐 속도를 늦추는 장치)일 뿐이다.</b> 일시적 변동성은 줄이지만 방향이나 수준은 못 바꾼다는 게 국제적 컨센서스(전문가들이 대체로 합의한 견해)이고, 중앙은행들도 알기 때문에 쏠림 완화 선에서만 들어간다.',
        '<b>스왑 시장이 현물보다 크다.</b> 스왑레이트(지금 환율과 나중에 되바꿀 환율의 차이)는 현물환율(지금 사고파는 환율)에서 선물환율(나중 시점으로 미리 정해둔 환율)을 뺀 값을 선물환율로 나눈 것이고, 이 값이 미국 금리에서 한국 금리를 뺀 값과 같아진다(커버드 금리평가). 여기서 결론이 나온다. 환헤지(환율 변동 위험을 없애려고 미리 값을 정해두는 것)를 하면 금리차익은 못 먹는다. 미국 금리가 높으니 자본이 빠진다는 설명이 헤지 비용까지 넣으면 성립하지 않는 이유이고, 브라질로 돈이 안 몰리는 이유도 같다.',
        '<b>2008년 위기의 구조.</b> 조선사가 선물환을 팔면 국내은행이 외국은행 지점과 3개월 스왑으로 헤지하고, 외국은행 지점은 받은 원화를 국내 채권에 투자했다. 리먼 때 본사 자금줄이 막혀 롤오버(만기가 오면 계약을 연장하는 것)가 끊기자 국내은행이 외화 부족에 빠졌다. 전세로 빌린 집을 팔아버리고 3년 뒤 완공될 아파트로 주겠다고 하다가 계약 연장이 끊긴 상황이라고 그는 비유한다.',
        '<b>지금은 그때가 아니다.</b> 최근 스왑레이트와 내외 금리차의 괴리가 거의 없거나 오히려 마이너스다. 자금이 남는 방향이라는 뜻이다. 지금의 원화 약세는 외화 자금경색 때문이 아니다.',
        '<b>경상수지(수출입과 소득으로 오간 돈의 차이)로도 설명이 안 된다.</b> 이론상 흑자면 원화가 강해져야 하는데, 2000년 이후 산점도는 상관관계가 거의 없고 오히려 약한 양(+)이다. 흑자가 늘 때 환율도 같이 올랐다는 뜻이다. 튀는 값 4건을 빼도 거의 0이다. 그는 이건 설명하기 어렵다고 인정한다.',
        '<b>포트폴리오 자금(주식과 채권에 오가는 외국인 투자금)도 뒤죽박죽이다.</b> 구간 1은 순유출인데 환율이 올랐고, 구간 6은 크게 빠졌는데 환율이 내렸다. 구간 8은 유출이 7보다 훨씬 큰데 환율은 소폭만 올랐다. 수급으로는 설명이 안 된다.',
        '<b>남는 답은 달러다.</b> 원화가 약해진 게 아니라 달러가 강해진 것이다. 원화는 달러 인덱스(주요 통화 대비 달러 값을 지수로 만든 것) 바스켓에 들어 있지도 않은데 2000년 이후 원/달러와 상관이 높다. 달러는 고래고 원화는 금붕어라 고래가 조금만 움직여도 전체가 끌려간다.',
        '<b>그 달러 인덱스를 끄는 건 미국 국채 수익률, 특히 10년물이다.</b> 사슬은 미국 국채 수익률에서 달러 인덱스로, 거기서 원/달러로 간다. NDF(원화를 실제로 주고받지 않고 차액만 정산하는 선물환) 딜러들이 가장 크게 참고하는 것도 달러 인덱스라고 전한다.',
        '<b>전망은 중기 기준 원화 강세 쪽이다.</b> 발언 시점이 약 1,480원인데 1,550원대에서 1,400원대까지, 약 10% 내려갈 수 있다는 개인 견해다. 근거는 한국 금리 정상화와 미국 금리가 더 오르기 어렵다는 판단이다. 단기 몇 개월 방향은 모른다고 선을 긋는다.',
