# 안 보인다. 3월 에너지 3부작이 물량 단절을 말하고, 6월에 전기값으로 옮겨 가고, 8월에 그 설비를
# 누가 지었나로 돌아오는 흐름이 섹션 넷에 흩어져 있다. 그래서 dc.render(top=...)에 넘기는
